ext('c11_math_ch11',[
C("🧭","दो विमा से तीन विमा",["रेखा पर एक संख्या काफ़ी","समतल में दो संख्याएँ (x, y)","अंतरिक्ष में तीन संख्याएँ (x, y, z)","ऊँचाई जुड़ने से z अक्ष आता है"],"अब तक आपने समतल में बिंदु लिखे हैं, जिसमें दो संख्याएँ चाहिए, एक्स और वाई। पर असली दुनिया में चीज़ें ऊँचाई भी रखती हैं। एक उड़ता हुआ पतंग सिर्फ़ आगे या बग़ल में नहीं, ज़मीन से ऊपर भी होता है। इसलिए अंतरिक्ष में किसी बिंदु को बताने के लिए तीन संख्याएँ चाहिए। एक्स, वाई और ज़ेड। ज़ेड ऊँचाई बताता है। इसी विचार को त्रिविमीय ज्यामिति कहते हैं। एक सीधी रेखा पर एक संख्या, समतल में दो और अंतरिक्ष में तीन संख्याएँ बिंदु की स्थिति तय करती हैं।"),
C("🧱","कमरे के कोने से समझिए",["कमरे का कोना मूल बिंदु","दो दीवारों और फ़र्श के मिलन की रेखाएँ अक्ष","छत की ओर ऊँचाई z","हर वस्तु की स्थिति तीन दूरियों से"],"कमरे का एक कोना सोचिए, जहाँ दो दीवारें और फ़र्श मिलते हैं। इस कोने को मूल बिंदु मान लीजिए। फ़र्श पर एक दीवार के साथ जाने वाली रेखा एक्स अक्ष है, दूसरी दीवार के साथ जाने वाली रेखा वाई अक्ष है और कोने से सीधे ऊपर जाने वाली रेखा ज़ेड अक्ष है। अब कमरे में कहीं भी रखी चीज़ की स्थिति तीन दूरियों से बताई जा सकती है। एक्स दिशा में कितना, वाई दिशा में कितना और ऊपर कितना। जैसे तीन, चार, दो। यही निर्देशांक कहलाते हैं।"),
C("✋","दाएँ हाथ का नियम",["x से y की ओर अँगुलियाँ मोड़ें","अँगूठा z की दिशा दिखाता है","यही मानक व्यवस्था है","ग़लत दिशा से चिह्न उलट जाएँगे"],"तीनों अक्षों की दिशा तय करने के लिए दाएँ हाथ का नियम काम आता है। दाएँ हाथ की अँगुलियों को एक्स अक्ष की ओर से वाई अक्ष की ओर मोड़िए। तब आपका अँगूठा जिस ओर इशारा करता है, वही ज़ेड अक्ष की धनात्मक दिशा है। यह मानक व्यवस्था है और सारी पुस्तकों में यही मानी जाती है। अगर आप दिशा उलटी ले लें, तो कई प्रश्नों में चिह्न उलट जाएँगे। इसलिए चित्र बनाते समय हमेशा इसी नियम का पालन कीजिए।"),
C("📍","अक्षों और तलों पर बिंदु",["x अक्ष पर बिंदु: (a, 0, 0)","y अक्ष पर: (0, b, 0)","z अक्ष पर: (0, 0, c)","XY तल पर z = 0, YZ तल पर x = 0"],"अब बिंदुओं की पहचान सीखिए। जो बिंदु एक्स अक्ष पर होता है, उसके वाई और ज़ेड शून्य होते हैं, जैसे ए, शून्य, शून्य। वाई अक्ष के बिंदु में एक्स और ज़ेड शून्य होते हैं। ज़ेड अक्ष के बिंदु में एक्स और वाई शून्य होते हैं। अब तलों की बात कीजिए। एक्स वाई तल में हर बिंदु की ऊँचाई शून्य होती है, इसलिए वहाँ ज़ेड बराबर शून्य है। वाई ज़ेड तल में एक्स बराबर शून्य और ज़ेड एक्स तल में वाई बराबर शून्य है। इन्हें याद कर लीजिए, ये बहुत बार काम आते हैं।"),
C("🔢","अष्टांश याद करने की ट्रिक",["पहला: (+,+,+)","ऊपर वाले चार: z धनात्मक","नीचे वाले चार: z ऋणात्मक","क्रम चौथाई की तरह घुमाएँ"],"तीनों तल मिलकर अंतरिक्ष को आठ भागों में बाँटते हैं, जिन्हें अष्टांश कहते हैं। इन्हें याद करने की सरल तरकीब सुनिए। पहला अष्टांश वह है जहाँ एक्स, वाई और ज़ेड तीनों धनात्मक हैं। ऊपर वाले चार भागों में ज़ेड धनात्मक रहता है और एक्स, वाई के चिह्न समतल के चार चौथाइयों की तरह घूमते हैं। नीचे वाले चार भागों में ज़ेड ऋणात्मक होता है और वही क्रम दोहराया जाता है। जैसे ऋण, धन, ऋण वाला बिंदु छठे अष्टांश में आता है। चिह्न देखकर अष्टांश बताना परीक्षा का आसान सवाल है।"),
Q("बिंदु (−2, 3, −4) किस अष्टांश में है और उसका XY तल पर प्रतिबिंब क्या है?","छठे अष्टांश में। प्रतिबिंब (−2, 3, 4), क्योंकि केवल z का चिह्न बदलता है।","एक छोटा सवाल। बिंदु ऋण दो, तीन, ऋण चार किस अष्टांश में है, और उसका एक्स वाई तल में प्रतिबिंब क्या होगा? सोचिए। ... चिह्न हैं ऋण, धन, ऋण, इसलिए यह छठे अष्टांश में है। एक्स वाई तल में प्रतिबिंब लेने पर केवल ज़ेड का चिह्न बदलता है, इसलिए प्रतिबिंब है ऋण दो, तीन, चार।"),
Q("बिंदु (3, 4, 5) की XY तल, x अक्ष और मूल बिंदु से दूरियाँ ज्ञात कीजिए।","XY तल से 5, x अक्ष से √41, मूल बिंदु से 5√2।","अब बिंदु तीन, चार, पाँच से तीन दूरियाँ निकालते हैं। एक्स वाई तल से दूरी ज़ेड का मान है, यानी पाँच। एक्स अक्ष से दूरी वाई और ज़ेड के वर्गों के योग का वर्गमूल है, यानी सोलह जमा पच्चीस का वर्गमूल, इकतालीस का वर्गमूल। मूल बिंदु से दूरी नौ, सोलह और पच्चीस के योग यानी पचास का वर्गमूल है, जो पाँच गुणा दो का वर्गमूल है।"),
C("📏","दूरी सूत्र कैसे बना",["पहले XY तल में कर्ण निकालें","फिर ऊँचाई के साथ दोबारा पाइथागोरस","d² = Δx² + Δy² + Δz²","दो बार पाइथागोरस का खेल"],"दूरी सूत्र को याद करने के बजाय समझ लीजिए कि यह कैसे बनता है। दो बिंदुओं के बीच एक्स और वाई के अंतर से पहले समतल में कर्ण निकालिए। वह पाइथागोरस प्रमेय से एक्स अंतर के वर्ग और वाई अंतर के वर्ग का जोड़ है। अब इस कर्ण को और ऊँचाई के अंतर को लेकर दूसरा समकोण त्रिभुज बनाइए, और फिर पाइथागोरस लगाइए। इस तरह तीनों अंतरों के वर्गों का जोड़ मिलता है। दूरी उसका वर्गमूल है। यानी पाइथागोरस दो बार लगा है, और सूत्र रटने की ज़रूरत ही नहीं।"),
Q("बिंदु A(1, 2, 3) और B(4, 6, 15) के बीच की दूरी ज्ञात कीजिए।","13","बिंदु एक, दो, तीन और चार, छह, पंद्रह के बीच दूरी निकालिए। अंतर हैं तीन, चार और बारह। वर्ग हैं नौ, सोलह और एक सौ चवालीस। जोड़ है एक सौ उनहत्तर। उसका वर्गमूल है तेरह। इसलिए दूरी तेरह इकाई है। ध्यान दीजिए, अंतर निकालते समय चिह्न की चिंता मत कीजिए, क्योंकि वर्ग करने पर वह धनात्मक हो जाता है।"),
Q("दिखाइए कि A(1, 2, 3), B(2, 3, 4), C(3, 4, 5) संरेख हैं।","AB = BC = √3 और AC = 2√3, इसलिए AB + BC = AC। अतः संरेख।","अब संरेखता यानी तीनों बिंदु एक ही रेखा पर हैं या नहीं, यह जाँचिए। ए बी की दूरी में तीनों अंतर एक-एक हैं, इसलिए ए बी तीन का वर्गमूल है। इसी तरह बी सी भी तीन का वर्गमूल है। ए सी में अंतर दो-दो-दो हैं, यानी बारह का वर्गमूल, जो दो गुणा तीन का वर्गमूल है। अब देखिए, ए बी जमा बी सी बराबर ए सी है। जब दो छोटी दूरियों का जोड़ सबसे बड़ी के बराबर हो, तो तीनों बिंदु एक रेखा पर होते हैं।"),
Q("A(0,0,0), B(3,0,0), C(0,4,0) से बने त्रिभुज का प्रकार बताइए।","AB = 3, AC = 4, BC = 5। 3² + 4² = 5², इसलिए A पर समकोण त्रिभुज।","अब त्रिभुज का प्रकार पहचानिए। मूल बिंदु ए, तीन-शून्य-शून्य बी और शून्य-चार-शून्य सी। ए बी की लंबाई तीन, ए सी की लंबाई चार और बी सी की लंबाई पाँच आती है। तीन के वर्ग और चार के वर्ग का जोड़ पच्चीस है, जो पाँच के वर्ग के बराबर है। इसलिए यह ए पर समकोण वाला त्रिभुज है। त्रिभुज के प्रश्नों में तीनों भुजाएँ निकालकर पाइथागोरस से जाँचना सबसे अच्छा तरीक़ा है।"),
C("🔀","विभाजन सूत्र का भाव",["रेखाखंड को m : n में बाँटना","आंतरिक विभाजन में योग m + n","बाह्य विभाजन में अंतर m − n","मध्य बिंदु m = n = 1"],"विभाजन सूत्र का मतलब है एक रेखाखंड को किसी अनुपात में बाँटने वाले बिंदु का निर्देशांक निकालना। अगर बिंदु दोनों के बीच आए, तो आंतरिक विभाजन कहते हैं और हर में एम जमा एन आता है। अगर बिंदु रेखाखंड के बाहर आए, तो बाह्य विभाजन कहते हैं और हर में एम ऋण एन आता है, साथ ही अंश में भी चिह्न बदल जाता है। जब अनुपात एक-एक हो, तो बिंदु ठीक बीच में आता है, यानी मध्य बिंदु। मध्य बिंदु तो बस दोनों बिंदुओं के निर्देशांकों का औसत है।"),
Q("A(2, 4, 6) और B(8, −2, 10) का मध्य बिंदु ज्ञात कीजिए।","(5, 1, 8)","मध्य बिंदु निकालना सबसे आसान है। एक्स का औसत, दो और आठ का जोड़ दस, आधा पाँच। वाई का औसत, चार और ऋण दो का जोड़ दो, आधा एक। ज़ेड का औसत, छह और दस का जोड़ सोलह, आधा आठ। इसलिए मध्य बिंदु है पाँच, एक, आठ। सिर्फ़ जोड़ना और दो से भाग देना है, इसलिए यह प्रश्न कभी न छोड़िए।"),
Q("A(1,2,3), B(6,7,8) को 2 : 3 में आंतरिक विभाजित करने वाले बिंदु के निर्देशांक ज्ञात कीजिए।","(3, 4, 5)","अब आंतरिक विभाजन। एम दो, एन तीन। एक्स निकालिए, दो गुणा छह जमा तीन गुणा एक, यानी पंद्रह, पाँच से भाग, तीन। वाई निकालिए, दो गुणा सात जमा तीन गुणा दो, यानी बीस, पाँच से भाग, चार। ज़ेड निकालिए, दो गुणा आठ जमा तीन गुणा तीन, यानी पच्चीस, पाँच से भाग, पाँच। बिंदु है तीन, चार, पाँच। ध्यान रखिए, एम पहले बिंदु के साथ नहीं, दूसरे बिंदु के निर्देशांक के साथ गुणा होता है।"),
Q("A(2,3,4), B(4,5,6) को 3 : 1 में बाह्य विभाजित करने वाला बिंदु ज्ञात कीजिए।","(5, 6, 7)","बाह्य विभाजन में हर होता है एम ऋण एन, यानी तीन ऋण एक, दो। एक्स, तीन गुणा चार ऋण एक गुणा दो, यानी दस, दो से भाग, पाँच। वाई, तीन गुणा पाँच ऋण एक गुणा तीन, यानी बारह, दो से भाग, छह। ज़ेड, तीन गुणा छह ऋण एक गुणा चार, यानी चौदह, दो से भाग, सात। बिंदु है पाँच, छह, सात। देखिए, यह बिंदु बी के आगे पड़ता है, यानी रेखाखंड के बाहर।"),
Q("A(1,2,3), B(4,5,6), C(7,8,9) वाले त्रिभुज का केंद्रक निकालिए।","(4, 5, 6)","केंद्रक यानी त्रिभुज की तीनों माध्यिकाओं का मिलन बिंदु। इसके निर्देशांक तीनों शीर्षों के निर्देशांकों के औसत हैं। एक्स, एक, चार और सात का जोड़ बारह, तीन से भाग, चार। वाई, दो, पाँच और आठ का जोड़ पंद्रह, तीन से भाग, पाँच। ज़ेड, तीन, छह और नौ का जोड़ अठारह, तीन से भाग, छह। केंद्रक चार, पाँच, छह है। यही बिंदु हर माध्यिका को दो एक के अनुपात में बाँटता है।"),
Q("उन बिंदुओं का बिंदुपथ क्या है जो (1,0,0) और (−1,0,0) से समदूरस्थ हैं?","समीकरण x = 0, यानी YZ तल।","बिंदुपथ वाला प्रश्न देखिए। मान लीजिए बिंदु एक्स, वाई, ज़ेड है। एक, शून्य, शून्य से दूरी का वर्ग एक्स ऋण एक का वर्ग जमा वाई वर्ग जमा ज़ेड वर्ग। दूसरे बिंदु से दूरी का वर्ग एक्स जमा एक का वर्ग जमा वाई वर्ग जमा ज़ेड वर्ग। दोनों बराबर रखने पर एक्स वर्ग के आगे ऋण दो एक्स और धन दो एक्स का अंतर बचता है, जिससे चार एक्स बराबर शून्य, यानी एक्स बराबर शून्य। यह वाई ज़ेड तल है, जो दोनों बिंदुओं के बीच का लंब समद्विभाजक तल है।"),
],7)
